    private String scheduleEngineeringBoard(String commandId, String taskId, long dueTimeMillis,
            EngineeringBoardPayload payload) throws IOException {
        return scheduleEngineeringBoard(commandId, taskId, dueTimeMillis, payload, 0L);
    }

    private String scheduleEngineeringBoard(String commandId, String taskId, long dueTimeMillis,
            EngineeringBoardPayload payload, long durationMillis) throws IOException {
        requireEngineeringEnabled();
        requireOpen();
        requireWriter();
        requireNotPaused();
        requireText(commandId, "命令标识");
        requireText(taskId, "任务标识");
        requireEngineeringDuration(durationMillis, payload.action());
        EngineeringBoardPayload timed = payload.withFocus(durationMillis);
        String content = mapper.writeValueAsString(timed);
        // 正工时人物动作先落真实 BEGIN 屏障，到期才执行真正的董事动作；
        // 零工时只留给运行层内部系统日程（自动开/关会等），仍是单帧。
        PendingTask planned = engineeringPlannedTask(taskId, dueTimeMillis, durationMillis,
                PendingTask.ENGINEERING_BOARD_V1, content);
        String stored = state.commandContents().get(commandId);
        if (stored != null) {
            EngineeringBoardPayload recorded = mapper.readValue(stored,
                    EngineeringBoardPayload.class);
            if (recorded.focusMillis() != durationMillis
                    || !sameBoardIntent(recorded, payload)) {
                throw new IllegalArgumentException("同一命令标识不能对应不同内容");
            }
            requireSameSchedule(commandId, planned.taskId(), planned.dueTimeMillis(),
                    planned.phase(), planned.kind(), planned.payload());
            return state.commandOutcomes().get(commandId);
        }
        long now = state.timeMillis();
        requireSchedulable(dueTimeMillis, taskId);
        if (payload.opensAt() > 0 && payload.materialDeadline() < dueTimeMillis) {
            throw new IllegalArgumentException("材料截止不得早于召集到期");
        }
        requireEngineeringDirectorAtBegin(payload.companyPartyId(), payload.personPartyId(),
                payload.seatId(), payload.action(), now);
        requireEngineeringFocusWindow(payload.personPartyId(), now, dueTimeMillis, durationMillis,
                payload.action());
        return scheduleCompletionTask(planned, commandId, content);
    }

    private String scheduleEngineeringTask(String commandId, String taskId, long dueTimeMillis,
            String kind, EngineeringActionPayload action, long durationMillis) throws IOException {
        requireEngineeringEnabled();
        requireOpen();
        requireWriter();
        requireNotPaused();
        requireText(commandId, "命令标识");
        requireText(taskId, "任务标识");
        requireEngineeringDuration(durationMillis, action.action());
        EngineeringActionPayload timed = action.withFocus(durationMillis);
        String content = mapper.writeValueAsString(timed);
        // 正工时经理动作同样先落 BEGIN 屏障：屏障复核当前岗位/对象/焦点，到期才真正执行。
        PendingTask planned = engineeringPlannedTask(taskId, dueTimeMillis, durationMillis, kind,
                content);
        String stored = state.commandContents().get(commandId);
        if (stored != null) {
            EngineeringActionPayload recorded = mapper.readValue(stored,
                    EngineeringActionPayload.class);
            if (recorded.focusMillis() != durationMillis
                    || !sameActionIntent(recorded, action)) {
                throw new IllegalArgumentException("同一命令标识不能对应不同内容");
            }
            requireSameSchedule(commandId, planned.taskId(), planned.dueTimeMillis(),
                    planned.phase(), planned.kind(), planned.payload());
            return state.commandOutcomes().get(commandId);
        }
        long now = state.timeMillis();
        requireSchedulable(dueTimeMillis, taskId);
        requireEngineeringManagerAtBegin(action.companyPartyId(), action.personPartyId(),
                action.action(), now);
        requireEngineeringFocusWindow(action.personPartyId(), now, dueTimeMillis, durationMillis,
                action.action());
        return scheduleCompletionTask(planned, commandId, content);
    }

    /**
     * 把一次已冻结的人物工程动作计划成真实待办。
     *
     * <p>正工时动作（公开入口默认至少 1 毫秒）先落 {@link PendingTask#ENGINEERING_BEGIN_V1}
     * 屏障：到期时点 = {@code dueMillis - durationMillis}，payload 是携带原动作的兼容包装。
     * 屏障到期复核通过后才排真正的完成帧；被拒则不留完成帧。零工时只用于运行层内部构造的
     * 系统日程（自动开/关会、客户响应、物理完工子任务），保持单帧语义。</p>
     *
     * @param taskId         任务标识（屏障与完成帧不同标识，完成帧追加 {@code :finish}）
     * @param dueMillis      真实完成时点
     * @param durationMillis 声明工时
     * @param kind           完成帧种类
     * @param payloadJson    原动作 payload（逐字，不改字段）
     * @return 应当排程的待办
     * @throws IOException 包装序列化失败
     */
    private PendingTask engineeringPlannedTask(String taskId, long dueMillis, long durationMillis,
            String kind, String payloadJson) throws IOException {
        if (durationMillis <= 0) {
            return new PendingTask(taskId, dueMillis, WorldScheduler.Phase.RULES, kind, payloadJson);
        }
        EngineeringBeginPayload wrapper = new EngineeringBeginPayload(kind, dueMillis, payloadJson);
        return new PendingTask(taskId, dueMillis - durationMillis, WorldScheduler.Phase.RULES,
                PendingTask.ENGINEERING_BEGIN_V1, mapper.writeValueAsString(wrapper));
    }

    /** 工时不得为负；零只允许运行层内部系统日程（公开入口另行要求正工时）。 */
    private static void requireEngineeringDuration(long durationMillis, String action) {
        if (durationMillis < 0) {
            throw new IllegalArgumentException("工程动作工时不能为负：" + action + " "
                    + durationMillis);
        }
    }

    /** 公开入口必须声明正工时：外部/模型不能靠 0 工时绕过人物焦点。 */
    private static void requirePositiveEngineeringDuration(long durationMillis, String action) {
        if (durationMillis <= 0) {
            throw new IllegalArgumentException("公开工程入口必须声明正工时（内部系统日程不经过此入口）："
                    + action + " " + durationMillis);
        }
    }

    /** 同一命令重发必须指向同一意图与同一声明工时（按首次原文比较）。 */
    private static boolean sameBoardIntent(EngineeringBoardPayload recorded,
            EngineeringBoardPayload requested) {
        return recorded.equals(requested.withFocus(recorded.focusMillis()));
    }

    private static boolean sameActionIntent(EngineeringActionPayload recorded,
            EngineeringActionPayload requested) {
        return recorded.equals(requested.withFocus(recorded.focusMillis()));
    }

    /** BEGIN 复核：人物必须仍是该公司章程中的真实席位，席位不得由模型或调用方自填。 */
    private void requireEngineeringDirectorAtBegin(String companyPartyId, String personPartyId,
            String seatId, String action, long now) {
        requireText(personPartyId, "董事人物");
        BoardRun run = boardOfCompany(companyPartyId).orElse(null);
        if (run == null) {
            throw new IllegalArgumentException("该公司没有董事会：" + companyPartyId);
        }
        BoardModel.Charter charter = run.board().charter();
        if (!charter.companyPartyId().equals(companyPartyId)) {
            throw new IllegalStateException("董事会与实际公司不一致：" + companyPartyId);
        }
        String actual = charter.seatOf(personPartyId);
        if (actual == null) {
            throw new IllegalArgumentException("人物不在该公司董事席位中：" + personPartyId);
        }
        if (!actual.equals(seatId)) {
            throw new IllegalArgumentException("董事席位必须与当前章程一致："
                    + personPartyId + " -> " + actual);
        }
        if ("CONVENE".equals(action) || "CONVENE_APPOINTMENT".equals(action)
                || "CONVENE_WAIVER".equals(action)) {
            if (!actual.equals(charter.chairSeatId())
                    && !personPartyId.equals(chairPerson(charter))) {
                throw new IllegalArgumentException("只有章程主席可以召集：" + personPartyId);
            }
        }
    }

    /** BEGIN 复核：经理动作必须由该公司当前有效经理发起；系统物理完工不占经理焦点。 */
    private void requireEngineeringManagerAtBegin(String companyPartyId, String personPartyId,
            String action, long now) {
        requireEngineeringCompany(companyPartyId);
        if ("COMPLETE_WORK".equals(action)
                && (personPartyId == null || personPartyId.isBlank())) {
            return;
        }
        requireText(personPartyId, "经理人物");
        if (!activeManager(state.roles(), personPartyId, companyPartyId, now)) {
            throw new IllegalArgumentException("该人物不是本公司当前有效经理：" + personPartyId);
        }
    }

    /**
     * 人物焦点互斥：声明了正工时的动作在 {@code [due-duration, due)} 内占用本人焦点，不得与任何
     * 已排程/在办工作重叠。BEGIN 就是这个区间的起点：屏障必须落在当前时点之后。
     *
     * <p>同一人物跨公司、董事与经理兼任共享同一焦点；不同人物互不影响；
     * 系统客户事件与物理施工（无人物或零工时）不占焦点；同一会议也不豁免。</p>
     *
     * @return 该动作的真实开始（BEGIN）时点
     */
    private long requireEngineeringFocusWindow(String personPartyId, long now, long due,
            long durationMillis, String action) {
        if (durationMillis < 0) {
            throw new IllegalArgumentException("工程动作工时不能为负：" + action);
        }
        if (durationMillis == 0) {
            // 运行层内部系统日程（自动开/关会、客户响应、物理完工子任务）只占一个时点
            return due;
        }
        long begin = due - durationMillis;
        if (personPartyId == null || personPartyId.isBlank()) {
            if (begin <= now) {
                throw new IllegalArgumentException("工程动作的真实开始时点必须晚于当前时点："
                        + action + " " + begin);
            }
            return begin;
        }
        // 先按真实区间判重叠，再判“屏障必须落在未来”：同时有别的安排在办时，给出焦点冲突原因。
        InterviewModel.Interval slot = new InterviewModel.Interval(begin, due);
        for (InterviewModel.Interval busy : runtimeBusy(state, personPartyId, null, now)) {
            if (busy.overlaps(slot)) {
                throw new IllegalArgumentException("本人焦点已被占用："
                        + personPartyId + " " + begin + ".." + due);
            }
        }
        if (begin <= now) {
            throw new IllegalArgumentException("工程动作的真实开始时点必须晚于当前时点："
                    + action + " " + begin);
        }
        return begin;
    }

    private void requireEngineeringEnabled() {
        if (!manifest.hasEngineering() || engineeringConfig == null) {
            throw new IllegalStateException("当前运行未启用工程模块：" + manifest.rulesVersion());
        }
    }

    private EngineeringRun.CompanySpec requireEngineeringCompany(String companyPartyId) {
        requireEngineeringEnabled();
        requireText(companyPartyId, "工程公司");
        EngineeringRun.CompanySpec spec = engineeringConfig.specOf(companyPartyId);
        if (spec == null) {
            throw new IllegalArgumentException("未知工程公司：" + companyPartyId);
        }
        if (companyPartyId.equals(charter.companyPartyId())) {
            throw new IllegalArgumentException("本接口不接受制造业公司作为工程经营公司");
        }
        return spec;
    }

    /**
     * 公共董事/经理入口的最小明确正工时。
     *
     * <p>外部与模型都不能用 0 工时绕过人物焦点；真正的系统日程（自动开/关会、客户事件、
     * 物理完工）由运行层直接构造 payload，不经过这些入口。</p>
     */
    private static final long DEFAULT_FOCUS_MILLIS = 1L;

    private static String chairSeat(BoardModel.Charter charter) {
        return charter.chairSeatId();
    }

    /**
     * 董事会入口的公司绑定：章程公司用唯一治理董事会，工程公司用其冻结董事会。
     *
     * @param charterCompany 是否章程（制造）公司
     * @param charter        该公司唯一章程
     * @param board          该公司唯一董事会运行态
     */
    private record BoardCompany(boolean charterCompany, BoardModel.Charter charter,
                                BoardRun board) {
    }

    /**
     * 取董事会入口要求的公司绑定；同一公司只返回一份权威董事会。
     *
     * <p>工程公司仍走旧的 {@link #requireEngineeringCompany(String)}，错误文本与拒绝条件不变；
     * 章程公司改用治理子集里的唯一董事会，不复制到工程子集、也不新建账。</p>
     *
     * @param companyPartyId 公司组织
     * @return 公司绑定
     * @throws IllegalArgumentException 公司未知或没有董事会
     */
    private BoardCompany requireBoardCompany(String companyPartyId) {
        requireText(companyPartyId, "公司");
        if (charter != null && companyPartyId.equals(charter.companyPartyId())) {
            requireEngineeringEnabled();
            BoardRun governance = state.governance();
            if (governance == null) {
                throw new IllegalArgumentException("章程公司没有治理董事会：" + companyPartyId);
            }
            return new BoardCompany(true, governance.board().charter(), governance);
        }
        EngineeringRun.CompanySpec spec = requireEngineeringCompany(companyPartyId);
        BoardRun board = state.engineering() == null ? null
                : state.engineering().boardOf(companyPartyId);
        if (board == null) {
            throw new IllegalArgumentException("该公司没有董事会：" + companyPartyId);
        }
        return new BoardCompany(false, spec.charter(), board);
    }

    /** 章程公司不接受工程合同豁免议题：没有工程合同/客户账户可指向。 */
    private void requireNotCharterCompany(String companyPartyId, String action) {
        if (charter != null && companyPartyId != null
                && companyPartyId.equals(charter.companyPartyId())) {
            throw new IllegalArgumentException("制造章程公司没有工程合同议题（" + action + "）："
                    + companyPartyId);
        }
    }

    private static String chairPerson(BoardModel.Charter charter) {
        for (BoardModel.Seat seat : charter.seats()) {
            if (seat.seatId().equals(charter.chairSeatId())) {
                return seat.partyId();
            }
        }
        throw new IllegalStateException("章程缺少主席席");
    }

    private static String seatOfPerson(EngineeringRun.CompanySpec spec, String personPartyId) {
        return seatInCharter(spec.charter(), personPartyId);
    }

    private static String seatInCharter(BoardModel.Charter charter, String personPartyId) {
        requireText(personPartyId, "董事人物");
        String seat = charter.seatOf(personPartyId);
        if (seat == null) {
            throw new IllegalArgumentException("该人物不在公司章程席位中：" + personPartyId);
        }
        return seat;
    }

    /**
     * 排程首次发表一篇资料：实际发布时间等于任务到期，不能在排程期预造过去出版经历。
     *
     * <p>发布者必须是冻结的登记读者；公开受众不带对象，组织受众必须是已登记 ORGANIZATION，
     * 直投受众必须是登记读者。受众与发布者随文档冻结，追加版本不能修改。</p>
     *
     * @param commandId               外部命令标识
     * @param taskId                  任务标识，运行内不复用
     * @param dueTimeMillis           到期模拟毫秒，必须晚于当前时点
     * @param docId                   新资料标识
     * @param publisherPartyId        发布者（登记读者）
     * @param audience                受众
     * @param title                   标题
     * @param body                    正文；只是资料内容，不是系统指令
     * @param publicSourceDescription 公开来源描述
     * @param readDurationMillis      固定阅读耗时，必须为正
     * @param internalSourceIds       仅管理审计的内部来源标识
     * @return 规范化回报文本 {@code SCHEDULED:taskId}
     * @throws IOException              持久提交失败
     * @throws IllegalArgumentException 参数、受众或能力非法
     */
    public synchronized String schedulePublishDocument(String commandId, String taskId,
                                                       long dueTimeMillis, String docId,
                                                       String publisherPartyId,
                                                       InformationModel.Audience audience,
                                                       String title, String body,
                                                       String publicSourceDescription,
                                                       long readDurationMillis,
                                                       List<String> internalSourceIds)
            throws IOException {
        requireRoleReadingEnabled();
        if (manifest.hasDividend() && docId != null && docId.startsWith("dividend-public:")) {
            throw new IllegalArgumentException("分红公告空间由授权批保留，普通发表不得占用：" + docId);
        }
        if (docId != null && (docId.startsWith("periodic-material:")
                || docId.startsWith("company-statement:"))) {
            // 周期材料与公开财报两段出版只能由真实准备/授权发布链写入。
            throw new IllegalArgumentException("周期出版空间由授权链保留，普通发表不得占用：" + docId);
        }
        Objects.requireNonNull(audience, "受众");
        PublishPayload payload = new PublishPayload(commandId, docId, publisherPartyId,
                audience.kind().name(), audience.partyId() == null ? "" : audience.partyId(),
                title, body, publicSourceDescription, readDurationMillis,
                internalSourceIds == null ? List.of() : List.copyOf(internalSourceIds));
        return schedulePublish(commandId, taskId, dueTimeMillis, payload,
                PendingTask.INFORMATION_PUBLISH_V1);
    }

    /**
     * 排程给已有资料追加一版：沿用原发布者与受众，发布时间等于任务到期且必须晚于上一版。
     *
     * @param commandId               外部命令标识
     * @param taskId                  任务标识，运行内不复用
     * @param dueTimeMillis           到期模拟毫秒，必须晚于当前时点
     * @param docId                   已有资料标识
     * @param title                   标题
     * @param body                    正文
     * @param publicSourceDescription 公开来源描述
     * @param readDurationMillis      固定阅读耗时，必须为正
     * @param internalSourceIds       仅管理审计的内部来源标识
     * @return 规范化回报文本 {@code SCHEDULED:taskId}
     * @throws IOException              持久提交失败
     * @throws IllegalArgumentException 参数或能力非法
     */
    public synchronized String schedulePublishDocumentVersion(String commandId, String taskId,
                                                              long dueTimeMillis, String docId,
                                                              String title, String body,
                                                              String publicSourceDescription,
                                                              long readDurationMillis,
                                                              List<String> internalSourceIds)
            throws IOException {
        requireRoleReadingEnabled();
        requireText(docId, "资料标识");
        if (manifest.hasDividend() && docId.startsWith("dividend-public:")) {
            throw new IllegalArgumentException("分红公告空间由授权批保留，普通版本入口不得占用：" + docId);
        }
        if (docId.startsWith("periodic-material:") || docId.startsWith("company-statement:")) {
            throw new IllegalArgumentException("周期出版空间由授权链保留，普通版本入口不得占用：" + docId);
        }
        PublishPayload payload = new PublishPayload(commandId, docId, "", "", "",
                title, body, publicSourceDescription, readDurationMillis,
                internalSourceIds == null ? List.of() : List.copyOf(internalSourceIds));
        return schedulePublish(commandId, taskId, dueTimeMillis, payload,
                PendingTask.INFORMATION_PUBLISH_VERSION_V1);
    }

    /** 发表排程共用：命令幂等、固定受众校验与同批持久提交。 */
    private String schedulePublish(String commandId, String taskId, long dueTimeMillis,
                                   PublishPayload payload, String kind) throws IOException {
        requireOpen();
        requireWriter();
        requireNotPaused();
        requireText(commandId, "命令标识");
        requireText(taskId, "任务标识");
        requireText(payload.docId(), "资料标识");
        requireNotReservedDocId(payload.docId());
        requireText(payload.title(), "资料标题");
        requireText(payload.body(), "资料正文");
        if (payload.readDurationMillis() <= 0) {
            throw new IllegalArgumentException("阅读耗时必须为正毫秒："
                    + payload.readDurationMillis());
        }
        String content = mapper.writeValueAsString(payload);
        if (state.commandContents().containsKey(commandId)) {
            if (!content.equals(state.commandContents().get(commandId))) {
                throw new IllegalArgumentException("同一命令标识不能对应不同内容");
            }
            requireSameSchedule(commandId, taskId, dueTimeMillis, WorldScheduler.Phase.COMPLETION,
                    kind, content);
            return state.commandOutcomes().get(commandId);
        }
        requireSchedulable(dueTimeMillis, taskId);
        if (PendingTask.INFORMATION_PUBLISH_V1.equals(kind)) {
            requireText(payload.publisherPartyId(), "发布者");
            if (!informationConfig.readers().contains(payload.publisherPartyId())) {
                throw new IllegalArgumentException("发布者必须是冻结的登记读者："
                        + payload.publisherPartyId());
            }
            InformationModel.AudienceKind audienceKind =
                    InformationModel.AudienceKind.valueOf(payload.audienceKind());
            if (audienceKind == InformationModel.AudienceKind.ORGANIZATION) {
                requireParty(payload.audiencePartyId(),
                        OpeningRegistry.PartyKind.ORGANIZATION, "组织受众");
            } else if (audienceKind == InformationModel.AudienceKind.DIRECT) {
                requireParty(payload.audiencePartyId(), OpeningRegistry.PartyKind.PERSON,
                        "直投受众");
                if (!informationConfig.readers().contains(payload.audiencePartyId())) {
                    throw new IllegalArgumentException("直投对象必须是冻结的登记读者："
                            + payload.audiencePartyId());
                }
            }
        }
        PendingTask task = new PendingTask(taskId, dueTimeMillis, WorldScheduler.Phase.COMPLETION,
                kind, content);
        return scheduleCompletionTask(task, commandId, content);
    }

    /**
     * 排程开始阅读一个明确版本：到期才预留工时，并同批排唯一匹配的自动完成待办。
     *
     * @param commandId     外部命令标识
     * @param taskId        任务标识，运行内不复用
     * @param dueTimeMillis 到期模拟毫秒，必须晚于当前时点
     * @param personPartyId 读者（登记人物）
     * @param docId         资料标识
     * @param version       明确版本号，必须为正
     * @return 规范化回报文本 {@code SCHEDULED:taskId}
     * @throws IOException              持久提交失败
     * @throws IllegalArgumentException 参数或能力非法
     */
    public synchronized String scheduleStartReading(String commandId, String taskId,
                                                    long dueTimeMillis, String personPartyId,
                                                    String docId, long version)
            throws IOException {
        requireRoleReadingEnabled();
        requireOpen();
        requireWriter();
        requireNotPaused();
        requireText(commandId, "命令标识");
        requireText(taskId, "任务标识");
        requireText(personPartyId, "阅读者");
        requireText(docId, "资料标识");
        if (version < 1) {
            throw new IllegalArgumentException("阅读版本必须从 1 开始：" + version);
        }
        requireParty(personPartyId, OpeningRegistry.PartyKind.PERSON, "阅读者");
        if (!informationConfig.readers().contains(personPartyId)) {
            throw new IllegalArgumentException("阅读者必须是冻结的登记读者：" + personPartyId);
        }
        ReadingPayload payload = new ReadingPayload(commandId, personPartyId, docId, version, "", 0L);
        String content = mapper.writeValueAsString(payload);
        if (state.commandContents().containsKey(commandId)) {
            if (!content.equals(state.commandContents().get(commandId))) {
                throw new IllegalArgumentException("同一命令标识不能对应不同内容");
            }
            requireSameSchedule(commandId, taskId, dueTimeMillis, WorldScheduler.Phase.COMPLETION,
                    PendingTask.INFORMATION_START_READ_V1, content);
            return state.commandOutcomes().get(commandId);
        }
        requireSchedulable(dueTimeMillis, taskId);
        // 单人物焦点：本人还有未完成的群组动作时不能开始新阅读
        requireNoGroupAction(personPartyId, state.pending());
        // 反向互斥：本人正有董事/经理正工时，不能同时开始阅读。
        // 判权必须用真实阅读区间 [due, due+readDuration)，不能把 now→未来到期整段当占用，
        // 否则“阅读在预约开始前结束”的合法日程会被误挡。
        if (manifest.hasEngineering()) {
            long readEnd = dueTimeMillis + readDurationOf(docId, version);
            if (engineeringFocusConflicts(state, personPartyId, dueTimeMillis, readEnd)) {
                throw new IllegalArgumentException("本人焦点已被董事/经理动作占用，不能同时阅读："
                        + personPartyId);
            }
        }
        PendingTask task = new PendingTask(taskId, dueTimeMillis, WorldScheduler.Phase.COMPLETION,
                PendingTask.INFORMATION_START_READ_V1, content);
        return scheduleCompletionTask(task, commandId, content);
    }

    /**
     * 排程取消一张活动阅读：到期后只取消本单，并只移除本单对应的自动完成待办。
     *
     * <p>入口按<b>本人范围引用</b>（所属人物 + 资料 + 固定版本 + 本人阅读序号）解析，不接受管理端全局
     * {@code READ-n} 序号，因此别人多读或少读都不会改变本单的取消语义。</p>
     *
     * @param commandId     外部命令标识
     * @param taskId        任务标识，运行内不复用
     * @param dueTimeMillis 到期模拟毫秒，必须晚于当前时点
     * @param personPartyId 读者（登记人物）
     * @param ref           本人范围引用（来自 {@link RoleView.ReadingRef}）
     * @return 规范化回报文本 {@code SCHEDULED:taskId}
     * @throws IOException              持久提交失败
     * @throws IllegalArgumentException 参数、引用归属或能力非法
     */
    public synchronized String scheduleCancelReading(String commandId, String taskId,
                                                     long dueTimeMillis, String personPartyId,
                                                     RoleView.ReadingRef ref)
            throws IOException {
        requireRoleReadingEnabled();
        requireOpen();
        requireWriter();
        requireNotPaused();
        requireText(commandId, "命令标识");
        requireText(taskId, "任务标识");
        requireText(personPartyId, "阅读者");
        Objects.requireNonNull(ref, "阅读引用");
        if (!ref.personPartyId().equals(personPartyId)) {
            throw new IllegalArgumentException("阅读引用不属于该人物：" + ref.personPartyId());
        }
        ReadingPayload payload = new ReadingPayload(commandId, personPartyId, ref.docId(),
                ref.version(), "", ref.index());
        String content = mapper.writeValueAsString(payload);
        if (state.commandContents().containsKey(commandId)) {
            if (!content.equals(state.commandContents().get(commandId))) {
                throw new IllegalArgumentException("同一命令标识不能对应不同内容");
            }
            requireSameSchedule(commandId, taskId, dueTimeMillis, WorldScheduler.Phase.COMPLETION,
                    PendingTask.INFORMATION_CANCEL_READ_V1, content);
            return state.commandOutcomes().get(commandId);
        }
        requireSchedulable(dueTimeMillis, taskId);
        PendingTask task = new PendingTask(taskId, dueTimeMillis, WorldScheduler.Phase.COMPLETION,
                PendingTask.INFORMATION_CANCEL_READ_V1, content);
        return scheduleCompletionTask(task, commandId, content);
    }

    /** 登记人物/组织种类：只读取固定开局登记，不信任调用方声明。 */
    private void requireParty(String partyId, OpeningRegistry.PartyKind kind, String field) {
        OpeningRegistry.Party party = partyOf(partyId);
        if (party == null || party.kind() != kind) {
            throw new IllegalArgumentException(field + "未登记或种类不符：" + partyId);
        }
    }

    /** 在固定开局登记里按标识查主体；不存在返回 null。 */
    private OpeningRegistry.Party partyOf(String partyId) {
        if (registry == null || partyId == null) {
            return null;
        }
        for (OpeningRegistry.Party party : registry.parties()) {
            if (party.partyId().equals(partyId)) {
                return party;
            }
        }
        return null;
    }

    /**
     * 推进到目标模拟毫秒：按公平顺序执行到期待办，再为时钟边界落一个完整批次。
     *
     * @param inclusiveMillis 目标模拟毫秒，不得早于当前时间
     * @throws IOException 持久提交失败；此时运行暂停、状态不前进
     */
    public synchronized void advanceTo(long inclusiveMillis) throws IOException {
        requireOpen();
        requireWriter();
        if (paused) {
            throw new IllegalStateException("运行已暂停，须恢复后继续");
        }
        if (inclusiveMillis < state.timeMillis()) {
            throw new IllegalArgumentException("世界时间不能倒退：" + state.timeMillis());
        }
        try {
            long limit = decisionLimit(inclusiveMillis);
            boolean stopsAtBarrier = stopsAtDecisionBarrier(inclusiveMillis);
            while (true) {
                PendingTask next = peek(limit);
                if (next == null) {
                    break;
                }
                switch (next.kind()) {
                    case PendingTask.CASH_TRANSFER_V1 -> completeTransfer(next);
                    case PendingTask.TRANSFER_NOTICE_V1 -> deliverNotice(next);
                    case PendingTask.SELL_RESERVE_V1 -> completeReserve(next);
                    case PendingTask.SELL_CANCEL_V1 -> completeCancel(next);
                    case PendingTask.FILL_SETTLE_V1 -> completeFill(next);
                    case PendingTask.EXCHANGE_ORDER_V1 -> completeOrder(next);
                    case PendingTask.EXCHANGE_CANCEL_V1 -> completeCancelOrder(next);
                    case PendingTask.EXCHANGE_CLOSE_V1 -> completeCloseMarket(next);
                    case PendingTask.MANUFACTURING_PURCHASE_ORDER_V1,
                         PendingTask.MANUFACTURING_PRODUCTION_V1,
                         PendingTask.MANUFACTURING_SALES_CONTRACT_V1,
                         PendingTask.MANUFACTURING_DELIVERY_V1,
                         PendingTask.MANUFACTURING_COLLECT_RECEIVABLE_V1,
                         PendingTask.MANUFACTURING_PAY_EXPENSE_BILL_V1 -> completeManufacturing(next);
                    case PendingTask.MANUFACTURING_GOODS_RECEIPT_V1,
                         PendingTask.MANUFACTURING_BATCH_COMPLETION_V1,
                         PendingTask.MANUFACTURING_AUTO_COLLECTION_V1 -> completeManufacturingChild(next);
                    case PendingTask.MANUFACTURING_PERIOD_CLOSE_V1 -> completePeriodClose(next);
                    case PendingTask.GOVERNANCE_MEETING_V1,
                         PendingTask.GOVERNANCE_MATERIAL_V1,
                         PendingTask.GOVERNANCE_BUDGET_PROPOSAL_V1,
                         PendingTask.GOVERNANCE_VOTE_V1,
                         PendingTask.GOVERNANCE_IMPLEMENT_V1 -> completeGovernance(next);
                    case PendingTask.BOARD_OPEN_V1 -> completeBoardOpen(next);
                    case PendingTask.BOARD_CLOSE_V1 -> completeBoardClose(next);
                    case PendingTask.BOARD_REVIEW_V1 -> completeBoardReview(next);
                    case PendingTask.ENGINEERING_BEGIN_V1 -> completeEngineeringBegin(next);
                    case PendingTask.ENGINEERING_BOARD_V1,
                         PendingTask.BOARD_ATTEND_V1 -> completeEngineeringBoard(next);
                    case PendingTask.ENGINEERING_ACTION_V1 -> completeEngineeringAction(next);
                    case PendingTask.ENGINEERING_PERIODIC_V1 -> completeEngineeringPeriodic(next);
                    case PendingTask.PERIOD_CAPTURE_V1 -> completePeriodCapture(next);
                    case PendingTask.PERIOD_CLOSE_V1 -> completePeriodCloseTask(next);
                    case PendingTask.PERIOD_DISCLOSURE_DEADLINE_V1 ->
                            completePeriodDeadline(next);
                    case PendingTask.CUSTOMER_EVENT_V1 -> completeCustomerEvent(next);
                    case PendingTask.ROLE_APPOINT_V1,
                         PendingTask.ROLE_REVOKE_V1 -> completeRole(next);
                    case PendingTask.INFORMATION_PUBLISH_V1,
                         PendingTask.INFORMATION_PUBLISH_VERSION_V1,
                         PendingTask.INFORMATION_START_READ_V1,
                         PendingTask.INFORMATION_CANCEL_READ_V1,
                         PendingTask.INFORMATION_COMPLETE_READ_V1 -> completeInformation(next);
                    case PendingTask.ROLE_TRADING_READ_V1,
                         PendingTask.ROLE_TRADING_UNREAD_V1 -> completeRoleReading(next);
                    case PendingTask.ROLE_TRADING_RESEARCH_V1,
                         PendingTask.ROLE_TRADING_TARGET_V1,
                         PendingTask.ROLE_TRADING_REVIEW_V1,
                         PendingTask.ROLE_TRADING_CONFIRM_V1,
                         PendingTask.ROLE_TRADING_HALT_V1,
                         PendingTask.ROLE_TRADING_CANCEL_V1,
                         PendingTask.ROLE_TRADING_CHILD_V1,
                         PendingTask.ROLE_TRADING_CHILD_CANCEL_V1,
                         PendingTask.ROLE_TRADING_BELIEF_V1,
                         PendingTask.ROLE_TRADING_FORECAST_V1,
                         PendingTask.ROLE_TRADING_COMPANY_REPORT_V1 -> completeRoleAction(next);
                    case PendingTask.ROLE_TRADING_COMPANY_FACT_CAPTURE_V1 ->
                            completeBeliefCapture(next);
                    case PendingTask.INFORMATION_BELIEF_PUBLISH_FACT_V1 ->
                            completeBeliefPublish(next);
                    case PendingTask.MEDIA_STORY_PROPOSE_V1,
                         PendingTask.MEDIA_STORY_SUBMIT_V1,
                         PendingTask.MEDIA_STORY_REVIEW_V1,
                         PendingTask.MEDIA_STORY_PUBLISH_V1,
                         PendingTask.MEDIA_STORY_CORRECTION_V1,
                         PendingTask.MEDIA_WORK_CANCEL_V1,
                         PendingTask.MEDIA_EVIDENCE_SHARE_V1 -> completeMediaTask(next);
                    case PendingTask.SOCIAL_BEGIN_V1,
                         PendingTask.SOCIAL_FINISH_V1,
                         PendingTask.SOCIAL_DELIVER_V1,
                         PendingTask.SOCIAL_BLOCK_V1,
                         PendingTask.SOCIAL_UNBLOCK_V1 -> completeSocialTask(next);
                    case PendingTask.GROUP_BEGIN_V1,
                         PendingTask.GROUP_FINISH_V1,
                         PendingTask.GROUP_PUBLISH_V1 -> completeGroupTask(next);
                    case PendingTask.INTERVIEW_INVITE_V1,
                         PendingTask.INTERVIEW_RESPOND_V1,
                         PendingTask.INTERVIEW_CANCEL_V1,
                         PendingTask.INTERVIEW_END_V1,
                         PendingTask.INTERVIEW_START_GATE_V1,
                         PendingTask.INTERVIEW_MISS_GATE_V1,
                         PendingTask.INTERVIEW_END_GATE_V1,
                         PendingTask.INTERVIEW_TTL_GATE_V1,
                         PendingTask.INTERVIEW_SPEAK_V1,
                         PendingTask.INTERVIEW_DIALOGUE_DEADLINE_V1 -> completeInterviewTask(next);
                    case PendingTask.ROLE_TRADING_SWEEP_V1 -> completeRoleSweep(next);
                    case PendingTask.ROLE_TRADING_EXPIRE_V1 -> completeRoleExpire(next);
                    case PendingTask.ROLE_TRADING_APPOINTMENT_END_V1 -> completeAppointmentEnd(next);
                    case PendingTask.ROLE_TRADING_HALT_RELEASE_V1 -> completeHaltRelease(next);
                    case PendingTask.DIVIDEND_MEETING_V1,
                         PendingTask.GOVERNANCE_DIVIDEND_PROPOSAL_V1,
                         PendingTask.GOVERNANCE_DIVIDEND_IMPLEMENT_V1,
                         PendingTask.DIVIDEND_REGISTER_V1,
                         PendingTask.DIVIDEND_BOOK_EX_V1,
                         PendingTask.DIVIDEND_SETTLE_V1,
                         PendingTask.DIVIDEND_IMPAIR_V1 -> completeDividend(next);
                    default -> throw new IllegalStateException("未启用的任务种类：" + next.kind());
                }
            }
            if (stopsAtBarrier) {
                // 停在最早未决屏障之前：只把时钟推到屏障，不落观察批次；已在屏障时不加空批。
                if (limit > state.timeMillis()) {
                    String content = "{\"timeMillis\":" + limit + "}";
                    WorldState candidate = next(limit,
                            WorldScheduler.Phase.COMPLETION.name(), state.accounts(),
                            state.pending(), state.delivered(), state.usedTaskIds(),
                            state.commandContents(), state.commandOutcomes(), state.securities(),
                            state.exchange());
                    commitAndApply("barrier:" + limit, content, "BARRIER_REACHED",
                            List.of(new WorldEvent("barrier:" + limit, "DECISION_BARRIER_V1",
                                    content)), candidate);
                }
                return;
            }
            if (inclusiveMillis > state.timeMillis()) {
                String content = "{\"timeMillis\":" + inclusiveMillis + "}";
                WorldState candidate = next(inclusiveMillis,
                        WorldScheduler.Phase.OBSERVATION.name(), state.accounts(), state.pending(),
                        state.delivered(), state.usedTaskIds(), state.commandContents(),
                        state.commandOutcomes(), state.securities(), state.exchange());
                commitAndApply("clock:" + inclusiveMillis, content, "ADVANCED",
                        List.of(new WorldEvent("clock:" + inclusiveMillis, "CLOCK_ADVANCED_V1",
                                content)), candidate);
            }
        } catch (RuntimeException failure) {
            // 内部执行期（含 ID 冲突、序列化、溢出）失败同样进入暂停，保留旧快照
            paused = true;
            throw failure;
        }
    }

    /**
     * 新档决定输入超过冻结上限：类型化失败，只带安全数值，不携带输入正文或凭据。
     *
     * <p>继承 {@link IllegalArgumentException} 保持旧调用方兼容；固定错误码
     * {@link #CODE}，宿主据此展示明确原因，不得吞成无诊断的拒绝。</p>
     */
    public static final class DecisionInputTooLargeException extends IllegalArgumentException {

        /** 固定错误码。 */
        public static final String CODE = "INPUT_TOO_LARGE";

        private final long actualChars;
        private final long actualBytes;
        private final long maxChars;
        private final long maxBytes;

        /**
         * 记录超限事实。
         *
         * @param actualChars 冻结输入的 UTF-16 字符数
         * @param actualBytes 冻结输入的 UTF-8 字节数
         * @param maxChars    冻结的字符上限
         * @param maxBytes    冻结的字节上限
         */
        public DecisionInputTooLargeException(long actualChars, long actualBytes, long maxChars,
                                              long maxBytes) {
            super("决定输入超过冻结上限（" + CODE + "）");
            this.actualChars = actualChars;
            this.actualBytes = actualBytes;
            this.maxChars = maxChars;
            this.maxBytes = maxBytes;
        }

        /** @return 固定错误码 */
        public String code() {
            return CODE;
        }

        /** @return 实际字符数 */
        public long actualChars() {
            return actualChars;
        }

        /** @return 实际 UTF-8 字节数 */
        public long actualBytes() {
            return actualBytes;
        }

        /** @return 冻结字符上限 */
        public long maxChars() {
            return maxChars;
        }

        /** @return 冻结字节上限 */
        public long maxBytes() {
            return maxBytes;
        }
    }

    /** 输入实际字符/UTF-8 字节必须同时落在冻结上限内；不做任何截断。 */
    private static void requireInputWithinLimits(String input, DecisionModel.Limits limits) {
        long chars = input.length();
        long bytes = input.getBytes(java.nio.charset.StandardCharsets.UTF_8).length;
        if (chars > limits.maxInputChars() || bytes > DecisionModel.MAX_INPUT_BYTES) {
            throw new DecisionInputTooLargeException(chars, bytes, limits.maxInputChars(),
                    DecisionModel.MAX_INPUT_BYTES);
        }
    }

    /** @return 当前管理端快照（只读、同一提交位置） */
    public synchronized Snapshot snapshot() {
        return snapshotOf(state);
    }

    /**
     * 把一个已解码状态投影为对外只读快照。
     *
     * <p>实时视图与历史视图共用这一处投影，避免两套口径：同一 position 的历史投影必然等于
     * 当时实时投影。</p>
     *
     * @param source 已解码状态
     * @return 只读快照
     */
    private static Snapshot snapshotOf(WorldState source) {
        return new Snapshot(source.position(), source.timeMillis(), source.lastPhase(),
                source.accounts(), Optional.ofNullable(source.securities()),
                Optional.ofNullable(source.exchange()), Optional.ofNullable(source.manufacturing()),
                Optional.ofNullable(source.governance()), Optional.ofNullable(source.roles()),
                Optional.ofNullable(source.information()), Optional.ofNullable(source.trading()),
                Optional.ofNullable(source.decisions()),
                source.pending(), source.delivered(), source.usedTaskIds(),
                Optional.ofNullable(source.dividends()), Optional.ofNullable(source.media()),
                Optional.ofNullable(source.evidence()), Optional.ofNullable(source.social()),
                Optional.ofNullable(source.engineering()));
    }

    /**
     * 一条已确认历史索引项：只描述记录本身，不含角色私源与正文。
     *
     * @param position   确认位置（从 1 开始）
     * @param commandId  当时的命令标识
     * @param result     当时的回报原文
     * @param eventCount 该批次的事件条数
     */
    public record HistoryEntry(long position, String commandId, String result, int eventCount) {

        /** 校验位置、标识与条数。 */
        public HistoryEntry {
            if (position < 1) {
                throw new IllegalArgumentException("历史位置必须从 1 开始：" + position);
            }
            if (commandId == null || commandId.isBlank() || result == null) {
                throw new IllegalArgumentException("历史命令与回报不能为空");
            }
            if (eventCount < 0) {
                throw new IllegalArgumentException("历史事件条数不能为负");
            }
        }
    }

    /**
     * 固定位置的历史帧：同一份解码结果同时给快照与群组子集，不让面板各自取数。
     *
     * @param snapshot 该位置的只读快照（与实时视图同一投影口径）
     * @param groups   该位置的群组/平台子集；未启用时为空
     */
    public record HistoryFrame(Snapshot snapshot, Optional<GroupsRun> groups) {

        /** 校验非空。 */
        public HistoryFrame {
            Objects.requireNonNull(snapshot, "snapshot");
            groups = Objects.requireNonNull(groups, "groups");
        }
    }

    /**
     * 已确认历史索引：按位置升序分页，只读，不推进世界、不写日志、不调用模型。
     *
     * <p>用位置而非时间截断：同一模拟毫秒可以有多个确认批次，后一笔不会泄入前一笔。</p>
     *
     * @param afterPosition 只返回位置严格大于此值的批次；0 表示从头开始
     * @param limit         本次最多返回条数，1..{@link #MAX_HISTORY_PAGE}
     * @return 不可变索引列表，按位置升序
     */
    public synchronized List<HistoryEntry> historyIndex(long afterPosition, int limit) {
        requireOpen();
        if (afterPosition < 0) {
            throw new IllegalArgumentException("历史起始位置不能为负：" + afterPosition);
        }
        if (limit <= 0 || limit > MAX_HISTORY_PAGE) {
            throw new IllegalArgumentException("历史分页条数必须在 1 到 " + MAX_HISTORY_PAGE
                    + " 之间，收到 " + limit);
        }
        List<HistoryEntry> entries = new ArrayList<>();
        for (WorldCommit commit : journal.commitsAfter(afterPosition, limit)) {
            entries.add(new HistoryEntry(commit.position(), commit.commandId(), commit.result(),
                    commit.events().size()));
        }
        return List.copyOf(entries);
    }

    /**
     * 固定确认位置的历史帧：解码该批次自带的 STATE_SNAPSHOT_V1。
     *
     * <p>只读：不改当前状态、不推进时钟、不追加日志、不写审计、不产生阅读/回忆/预算消耗。
     * 未确认位置明确拒绝，不夹取到最近位置。</p>
     *
     * @param position 确认位置（1..当前确认位置）
     * @return 该位置的只读帧
     * @throws IllegalArgumentException 位置未确认
     */
    public synchronized HistoryFrame historyFrame(long position) {
        requireOpen();
        requireOwnPosition(position, "historyFrame");
        long cut = state.position();
        if (position < 1 || position > cut) {
            throw new IllegalArgumentException("位置未确认：" + position + "（当前确认到 " + cut + "）");
        }
        WorldCommit commit = journal.commitAt(position).orElseThrow(
                () -> new IllegalStateException("确认历史缺少位置 " + position));
        WorldState decoded;
        try {
            decoded = decodeSnapshot(commit);
        } catch (IOException invalid) {
            throw new IllegalStateException("确认历史快照无法解码：" + position, invalid);
        }
        requireSameConfirmedFrame(decoded, position);
        return new HistoryFrame(snapshotOf(decoded), Optional.ofNullable(decoded.groups()));
    }

    /** 历史帧的事实来源：父运行前缀（只读继承）还是本运行自有帧。 */
    public enum HistorySource {
        /** 父运行 {@code 1..p}：已逐帧验证的只读继承事实，不属于本运行产生。 */
        PARENT_PREFIX,
        /** 本运行自有确认帧（普通运行从 1 开始，分支子档从 p+1 开始）。 */
        CHILD
    }

    /**
     * 带来源标注的历史索引项。
     *
     * @param position    确认位置
     * @param source      事实来源
     * @param sourceRunId 产生该帧的运行标识（父前缀为父运行，自有帧为本运行）
     * @param commandId   当时的命令标识
     * @param result      当时的回报原文
     * @param eventCount  该批次事件条数
     */
    public record BranchHistoryEntry(long position, HistorySource source, String sourceRunId,
                                     String commandId, String result, int eventCount) {
    }

    /**
     * 带来源标注的历史帧；继承帧的 {@code sourceRunId} 是父运行，明确不被伪装成本运行原帧。
     *
     * @param frame       该位置的只读帧（与实时视图同一投影口径）
     * @param source      事实来源
     * @param sourceRunId 产生该帧的运行标识
     */
    public record BranchHistoryFrame(HistoryFrame frame, HistorySource source,
                                     String sourceRunId) {
    }

    /**
     * 本运行的分支来源；普通运行返回空。
     *
     * @return 分支来源
     */
    public synchronized Optional<BranchOrigin> branchOrigin() {
        return Optional.ofNullable(branchOrigin);
    }

    /**
     * 按位置升序返回带来源标注的历史索引（只读，不推进世界、不写日志、不调用模型）。
     *
     * <p>普通运行与 {@link #historyIndex} 等价（全部标 {@code CHILD}）；分支子档额外包含
     * 父前缀 {@code 1..p}，标 {@code PARENT_PREFIX} 并给出父运行标识。这样面板可以按来源
     * 分列，不需要也不允许把父帧说成本运行帧。</p>
     *
     * @param afterPosition 只返回位置严格大于此值的批次；0 表示从头开始
     * @param limit         本次最多返回条数，1..{@link #MAX_HISTORY_PAGE}
     * @return 不可变索引列表
     */
    public synchronized List<BranchHistoryEntry> branchHistoryIndex(long afterPosition, int limit) {
        requireOpen();
        if (afterPosition < 0) {
            throw new IllegalArgumentException("历史起始位置不能为负：" + afterPosition);
        }
        if (limit <= 0 || limit > MAX_HISTORY_PAGE) {
            throw new IllegalArgumentException("历史分页条数必须在 1 到 " + MAX_HISTORY_PAGE
                    + " 之间，收到 " + limit);
        }
        List<BranchHistoryEntry> entries = new ArrayList<>();
        for (WorldCommit commit : commitSource.commitsAfter(afterPosition, limit)) {
            boolean inherited = branchOrigin != null
                    && commit.position() <= branchOrigin.parentPosition();
            entries.add(new BranchHistoryEntry(commit.position(),
                    inherited ? HistorySource.PARENT_PREFIX : HistorySource.CHILD,
                    inherited ? branchOrigin.parentRunId() : manifest.runId(),
                    commit.commandId(), commit.result(), commit.events().size()));
        }
        return List.copyOf(entries);
    }

    /**
     * 按位置取带来源标注的历史帧；父前缀位置同样可读，但来源明确标成父运行。
     *
     * @param position 确认位置（1..当前确认位置）
     * @return 该位置的只读帧与来源
     * @throws IllegalArgumentException 位置未确认
     */
    public synchronized BranchHistoryFrame branchHistoryFrame(long position) {
        requireOpen();
        long cut = state.position();
        if (position < 1 || position > cut) {
            throw new IllegalArgumentException("位置未确认：" + position + "（当前确认到 " + cut + "）");
        }
        WorldCommit commit = commitSource.commitAt(position).orElseThrow(
                () -> new IllegalStateException("确认历史缺少位置 " + position));
        WorldState decoded;
        try {
            decoded = decodeSnapshot(commit);
        } catch (IOException invalid) {
            throw new IllegalStateException("确认历史快照无法解码：" + position, invalid);
        }
        if (decoded.position() != position || decoded.schemaVersion() != expectedSchema()) {
            throw new IllegalStateException("确认历史快照位置或版本不一致：" + position);
        }
        boolean inherited = branchOrigin != null && position <= branchOrigin.parentPosition();
        if (!inherited) {
            requireSameConfirmedFrame(decoded, position);
        }
        return new BranchHistoryFrame(
                new HistoryFrame(snapshotOf(decoded), Optional.ofNullable(decoded.groups())),
                inherited ? HistorySource.PARENT_PREFIX : HistorySource.CHILD,
                inherited ? branchOrigin.parentRunId() : manifest.runId());
    }

    /**
     * 分支子档的父前缀位置不能经"本运行"入口读取或导出，否则会把父帧伪装成本运行原帧。
     *
     * @param position 位置
     * @param api      调用入口名，只用于说明
     * @throws IllegalArgumentException 位置属于父前缀
     */
    private void requireOwnPosition(long position, String api) {
        if (branchOrigin != null && position >= 1 && position <= branchOrigin.parentPosition()) {
            throw new IllegalArgumentException(BRANCH_INHERITED_POSITION_NOT_EXPORTABLE
                    + "：" + api + " 不接受父前缀位置 " + position
                    + "（父前缀 1.." + branchOrigin.parentPosition()
                    + "；请用 branchHistoryFrame 读取并标注来源）");
        }
    }

    /**
     * 确认历史帧与位置/运行/版本一致；恢复期已逐批校验，这里防的是错位取帧。
     *
     * @param decoded  解码状态
     * @param position 期望位置
     */
    private void requireSameConfirmedFrame(WorldState decoded, long position) {
        if (decoded.position() != position) {
            throw new IllegalStateException("确认历史快照位置不一致：期望 " + position
                    + "，实际 " + decoded.position());
        }
        if (!manifest.runId().equals(decoded.runId())) {
            throw new IllegalStateException("确认历史快照运行标识不一致：" + decoded.runId());
        }
        if (decoded.schemaVersion() != expectedSchema()) {
            throw new IllegalStateException("确认历史快照版本不支持：" + decoded.schemaVersion()
                    + "（本次运行需要 " + expectedSchema() + "）");
        }
    }

    /**
     * 确认边界检查点信封：导出与核验材料，不是可独立续跑的运行状态。
     *
     * @param checkpointVersion 外层格式版本
     * @param runId             运行标识
     * @param position          所选确认位置
     * @param cutPosition       导出时的确认截止位置；核验要求 position <= cutPosition <= 当时截止
     * @param timeMillis        该位置的模拟时点
     * @param lastPhase         该位置最后完成的阶段
     * @param manifest          运行清单
     * @param opening           开局提交内容（清单、开局现金、登记与各模块配置）
     * @param stateJson         该位置状态快照的规范化 JSON
     * @param stateDigest       上述内容的 SHA-256（规范化重序列化，非磁盘帧摘要）
     * @param stateDigestKind   摘要口径说明
     * @param commitCommandId   该位置批次的命令标识
     * @param commitResult      该位置批次的回报原文
     * @param commitEventCount  该位置批次的事件条数
     * @param commitDigest      整批规范化 JSON 的 SHA-256（同上，非磁盘帧摘要）
     * @param commitDigestKind  摘要口径说明
     * @param generatedAtEpochMillis 导出墙钟时刻
     * @param claims            本信封明确不主张的能力
     */
    public record Checkpoint(String checkpointVersion, String runId, long position, long cutPosition,
                             long timeMillis, String lastPhase, RunManifest manifest,
                             Map<String, Object> opening, String stateJson, String stateDigest,
                             String stateDigestKind, String commitCommandId, String commitResult,
                             int commitEventCount, String commitDigest, String commitDigestKind,
                             long generatedAtEpochMillis, Map<String, Object> claims) {
    }

    /**
     * 检查点核验结论。
     *
     * @param ok         是否通过
     * @param reason     通过为 OK，否则为原因码
     * @param runId      运行标识
     * @param position   被核验的位置
     * @param cutPosition 核验时的确认截止位置
     */
    public record CheckpointVerdict(boolean ok, String reason, String runId, long position,
                                    long cutPosition) {
    }

    /**
     * 导出所选确认位置的检查点信封（只读）。
     *
     * <p>摘要只对本进程重新序列化的内容计算，明确标注不是磁盘帧 SHA；也不能当作"完整日志证明"。</p>
     *
     * @param position 确认位置
     * @return 信封
     * @throws IOException 状态无法序列化
     * @throws IllegalArgumentException 位置未确认
     */
    public synchronized Checkpoint checkpoint(long position) throws IOException {
        requireOpen();
        requireOwnPosition(position, "checkpoint");
        long cut = state.position();
        if (position < 1 || position > cut) {
            throw new IllegalArgumentException("位置未确认：" + position + "（当前确认到 " + cut + "）");
        }
        WorldCommit commit = journal.commitAt(position).orElseThrow(
                () -> new IllegalStateException("确认历史缺少位置 " + position));
        WorldState decoded = decodeSnapshot(commit);
        requireSameConfirmedFrame(decoded, position);
        String stateJson = canonicalMapper.writeValueAsString(decoded);
        String commitJson = canonicalMapper.writeValueAsString(commit);
        Map<String, Object> claims = new LinkedHashMap<>();
        claims.put("independentResume", Boolean.FALSE);
        claims.put("branchSource", Boolean.FALSE);
        claims.put("journalPrefixSha256", Boolean.FALSE);
        claims.put("digestIsFileFrameSha256", Boolean.FALSE);
        claims.put("note", CHECKPOINT_CLAIMS_NOTE);
        return new Checkpoint(CHECKPOINT_VERSION, manifest.runId(), position, cut,
                decoded.timeMillis(), decoded.lastPhase(), manifest,
                openingContentMap(orderedOpenings), stateJson, sha256Hex(stateJson),
                STATE_DIGEST_KIND, commit.commandId(), commit.result(),
                commit.events().size(), sha256Hex(commitJson),
                COMMIT_DIGEST_KIND, System.currentTimeMillis(), claims);
    }

    /**
     * 结构化 JSON 值比较：对象键序无关，数组按序，数值按十进制值比较。
     *
     * <p>用于核对信封里的开局内容：既要忽略序列化键序，又不能让 1000.00 与 1000.0 误判为不同，
     * 同时任何真实数值改动都必须被判为不同。</p>
     *
     * @param left  期望值
     * @param right 提交值
     * @return 结构与数值都相同返回 true
     */
    private static boolean sameJson(JsonNode left, JsonNode right) {
        if (left == null || right == null) {
            return left == right;
        }
        if (left.isNumber() && right.isNumber()) {
            try {
                return left.decimalValue().compareTo(right.decimalValue()) == 0;
            } catch (NumberFormatException | ArithmeticException invalid) {
                return false;
            }
        }
        if (left.isObject() && right.isObject()) {
            if (left.size() != right.size()) {
                return false;
            }
            var names = left.fieldNames();
            while (names.hasNext()) {
                String name = names.next();
                if (!right.has(name) || !sameJson(left.get(name), right.get(name))) {
                    return false;
                }
            }
            return true;
        }
        if (left.isArray() && right.isArray()) {
            if (left.size() != right.size()) {
                return false;
            }
            for (int index = 0; index < left.size(); index++) {
                if (!sameJson(left.get(index), right.get(index))) {
                    return false;
                }
            }
            return true;
        }
        return left.equals(right);
    }

    /**
     * 核验检查点信封：只对照本运行同一确认位置的原始批次。
     *
     * <p>逐项绑定：版本、运行、位置（1..截止）、cutPosition（position..当前截止）、清单、
     * 开局内容、时点、阶段、状态、命令标识与回报、事件条数、整批摘要、两个摘要口径、
     * 四项能力声明与声明正文。顶层出现未约定字段即拒绝。
     * {@code generatedAtEpochMillis} 是导出墙钟，无法从帧重建，明确只做格式检查、不参与核验。</p>
     *
     * <p>摘要相等不算通过：即使篡改状态后重算了 SHA，也会在领域比较处失败。</p>
     *
     * @param envelopeJson 信封 JSON 原文
     * @return 核验结论
     */
    public synchronized CheckpointVerdict verifyCheckpoint(String envelopeJson) {
        requireOpen();
        long cut = state.position();
        String run = manifest.runId();
        if (envelopeJson == null || envelopeJson.isBlank()) {
            return new CheckpointVerdict(false, "CHECKPOINT_EMPTY", run, 0L, cut);
        }
        JsonNode root;
        try {
            // 用保留小数位的 mapper 解析：逐字段比较时不能把 1000.00 读成 Double。
            root = envelopeMapper.readTree(envelopeJson);
        } catch (IOException invalid) {
            return new CheckpointVerdict(false, "CHECKPOINT_NOT_JSON", run, 0L, cut);
        }
        if (root == null || !root.isObject()) {
            return new CheckpointVerdict(false, "CHECKPOINT_NOT_OBJECT", run, 0L, cut);
        }
        if (!CHECKPOINT_VERSION.equals(root.path("checkpointVersion").asText(""))) {
            return new CheckpointVerdict(false, "CHECKPOINT_VERSION_UNSUPPORTED", run, 0L, cut);
        }
        String envelopeRun = root.path("runId").asText("");
        if (!run.equals(envelopeRun)) {
            return new CheckpointVerdict(false, "CHECKPOINT_RUN_MISMATCH", run, 0L, cut);
        }
        long position;
        try {
            position = Long.parseLong(root.path("position").asText(""));
        } catch (NumberFormatException invalid) {
            return new CheckpointVerdict(false, "CHECKPOINT_POSITION_INVALID", run, 0L, cut);
        }
        if (position < 1 || position > cut) {
            return new CheckpointVerdict(false, "CHECKPOINT_POSITION_UNCONFIRMED", run, position, cut);
        }
        if (branchOrigin != null && position <= branchOrigin.parentPosition()) {
            // 父前缀位置不是本运行原帧：不导出、也不把父快照说成本运行的检查点
            return new CheckpointVerdict(false, BRANCH_INHERITED_POSITION_NOT_EXPORTABLE, run,
                    position, cut);
        }
        var fieldNames = root.fieldNames();
        while (fieldNames.hasNext()) {
            String field = fieldNames.next();
            if (!CHECKPOINT_FIELDS.contains(field)) {
                return new CheckpointVerdict(false, "CHECKPOINT_UNKNOWN_FIELD", run, position, cut);
            }
        }
        long cutPosition;
        try {
            cutPosition = Long.parseLong(root.path("cutPosition").asText(""));
        } catch (NumberFormatException invalid) {
            return new CheckpointVerdict(false, "CHECKPOINT_CUT_INVALID", run, position, cut);
        }
        if (cutPosition < position || cutPosition > cut) {
            return new CheckpointVerdict(false, "CHECKPOINT_CUT_INVALID", run, position, cut);
        }
        JsonNode generatedAt = root.get("generatedAtEpochMillis");
        if (generatedAt == null || !generatedAt.canConvertToLong() || generatedAt.asLong() < 0L) {
            return new CheckpointVerdict(false, "CHECKPOINT_GENERATED_AT_INVALID", run,
                    position, cut);
        }
        JsonNode manifestNode = root.get("manifest");
        RunManifest submittedManifest = null;
        if (manifestNode != null && manifestNode.isObject()) {
            try {
                submittedManifest = mapper.convertValue(manifestNode, RunManifest.class);
            } catch (IllegalArgumentException invalid) {
                submittedManifest = null;
            }
        }
        if (submittedManifest == null || !manifest.equals(submittedManifest)) {
            return new CheckpointVerdict(false, "CHECKPOINT_MANIFEST_MISMATCH", run, position, cut);
        }
        JsonNode openingNode = root.get("opening");
        if (openingNode == null || !openingNode.isObject()) {
            return new CheckpointVerdict(false, "CHECKPOINT_OPENING_MISMATCH", run, position, cut);
        }
        JsonNode expectedOpening;
        try {
            // 逐字段对照本运行开局提交内容；键序无关，数值按十进制值比较。
            expectedOpening = envelopeMapper.valueToTree(openingContentMap(orderedOpenings));
        } catch (IllegalArgumentException invalid) {
            return new CheckpointVerdict(false, "CHECKPOINT_OPENING_MISMATCH", run, position, cut);
        }
        if (!sameJson(expectedOpening, openingNode)) {
            return new CheckpointVerdict(false, "CHECKPOINT_OPENING_MISMATCH", run, position, cut);
        }
        JsonNode stateNode = root.get("stateJson");
        if (stateNode == null || !stateNode.isTextual()) {
            return new CheckpointVerdict(false, "CHECKPOINT_STATE_MISSING", run, position, cut);
        }
        WorldCommit commit = journal.commitAt(position).orElse(null);
        if (commit == null) {
            return new CheckpointVerdict(false, "CHECKPOINT_COMMIT_MISSING", run, position, cut);
        }
        WorldState reference;
        try {
            reference = decodeSnapshot(commit);
            requireSameConfirmedFrame(reference, position);
        } catch (IOException | RuntimeException invalid) {
            return new CheckpointVerdict(false, "CHECKPOINT_REFERENCE_UNREADABLE", run, position, cut);
        }
        long envelopeTime;
        try {
            envelopeTime = Long.parseLong(root.path("timeMillis").asText(""));
        } catch (NumberFormatException invalid) {
            return new CheckpointVerdict(false, "CHECKPOINT_TIME_MISMATCH", run, position, cut);
        }
        if (envelopeTime != reference.timeMillis()) {
            return new CheckpointVerdict(false, "CHECKPOINT_TIME_MISMATCH", run, position, cut);
        }
        if (!reference.lastPhase().equals(root.path("lastPhase").asText(""))) {
            return new CheckpointVerdict(false, "CHECKPOINT_PHASE_MISMATCH", run, position, cut);
        }
        WorldState submitted;
        try {
            submitted = (manifest.hasDecisions() ? decisionMapper : mapper)
                    .readValue(stateNode.asText(), WorldState.class);
        } catch (IOException | RuntimeException invalid) {
            return new CheckpointVerdict(false, "CHECKPOINT_STATE_UNREADABLE", run, position, cut);
        }
        if (!reference.equals(submitted)) {
            return new CheckpointVerdict(false, "CHECKPOINT_STATE_MISMATCH", run, position, cut);
        }
        if (!commit.commandId().equals(root.path("commitCommandId").asText(""))
                || !commit.result().equals(root.path("commitResult").asText(""))) {
            return new CheckpointVerdict(false, "CHECKPOINT_COMMIT_MISMATCH", run, position, cut);
        }
        if (commit.events().size() != root.path("commitEventCount").asInt(-1)) {
            return new CheckpointVerdict(false, "CHECKPOINT_COMMIT_EVENT_MISMATCH", run, position, cut);
        }
        String expectedCommitDigest;
        try {
            expectedCommitDigest = sha256Hex(canonicalMapper.writeValueAsString(commit));
        } catch (IOException invalid) {
            return new CheckpointVerdict(false, "CHECKPOINT_REFERENCE_UNREADABLE", run, position, cut);
        }
        if (!expectedCommitDigest.equals(root.path("commitDigest").asText(""))) {
            return new CheckpointVerdict(false, "CHECKPOINT_COMMIT_DIGEST_MISMATCH", run, position, cut);
        }
        if (!STATE_DIGEST_KIND.equals(root.path("stateDigestKind").asText(""))
                || !COMMIT_DIGEST_KIND.equals(root.path("commitDigestKind").asText(""))) {
            return new CheckpointVerdict(false, "CHECKPOINT_DIGEST_KIND_UNSUPPORTED", run, position, cut);
        }
        JsonNode claims = root.get("claims");
        if (claims == null || !claims.isObject() || claims.size() != 5) {
            return new CheckpointVerdict(false, "CHECKPOINT_CLAIM_MISMATCH", run, position, cut);
        }
        for (String claim : List.of("independentResume", "branchSource", "journalPrefixSha256",
                "digestIsFileFrameSha256")) {
            JsonNode value = claims.get(claim);
            if (value == null || !value.isBoolean() || value.booleanValue()) {
                return new CheckpointVerdict(false, "CHECKPOINT_CLAIM_MISMATCH", run, position, cut);
            }
        }
        if (!CHECKPOINT_CLAIMS_NOTE.equals(claims.path("note").asText(""))) {
            return new CheckpointVerdict(false, "CHECKPOINT_CLAIM_MISMATCH", run, position, cut);
        }
        String expectedDigest;
        try {
            expectedDigest = sha256Hex(canonicalMapper.writeValueAsString(reference));
        } catch (IOException invalid) {
            return new CheckpointVerdict(false, "CHECKPOINT_REFERENCE_UNREADABLE", run, position, cut);
        }
        if (!expectedDigest.equals(root.path("stateDigest").asText(""))) {
            return new CheckpointVerdict(false, "CHECKPOINT_DIGEST_MISMATCH", run, position, cut);
        }
        return new CheckpointVerdict(true, "OK", run, position, cut);
    }

    /**
     * 按公司取董事会（统一视图）：制造业来自旧 {@code governance} 单例，工程公司来自工程子集。
     *
     * <p>两处键域严格不交，因此同一公司只有一份权威；未知或未启用公司返回空，不伪造董事会。</p>
     *
     * @param companyPartyId 公司组织 partyId
     * @return 该公司董事会；不存在返回空
     */
    public synchronized Optional<BoardRun> boardOfCompany(String companyPartyId) {
        requireText(companyPartyId, "公司");
        if (state.engineering() != null) {
            BoardRun board = state.engineering().boardOf(companyPartyId);
            if (board != null) {
                return Optional.of(board);
            }
        }
        if (state.governance() != null
                && companyPartyId.equals(state.governance().board().charter()
                        .companyPartyId())) {
            return Optional.of(state.governance());
        }
        return Optional.empty();
    }

    /**
     * 只读：某人此刻是不是某公司的真实在任经理（周期授权与发布人判定用）。
     *
     * @param companyPartyId 公司组织
     * @param personPartyId 人物
     * @param at             判定时刻
     * @return 在任返回 true
     */
    public synchronized boolean isActiveManager(String companyPartyId, String personPartyId,
            long at) {
        return activeManager(state.roles(), personPartyId, companyPartyId, at);
    }

    /** 周期受信绑定所需的只读帧：公司章程、会议、资料、回忆参数与任职。 */
    public record PeriodicFrame(Map<String, BoardModel.Charter> charters,
                                Map<String, List<BoardModel.Meeting>> meetings,
                                InformationModel.State information,
                                CognitionRecall.Policy recallPolicy, RoleAccess.State roles) {
    }

    /**
     * 组装周期受信绑定帧：只读当前已确认状态，不复制账或正文。
     *
     * @return 受信绑定帧
     */
    public synchronized PeriodicFrame periodicFrame() {
        Map<String, BoardModel.Charter> charters = new LinkedHashMap<>();
        Map<String, List<BoardModel.Meeting>> meetings = new LinkedHashMap<>();
        if (state.engineering() != null) {
            for (String company : state.engineering().companyIds()) {
                BoardRun board = state.engineering().boardOf(company);
                if (board == null) {
                    continue;
                }
                charters.put(company, board.board().charter());
                List<BoardModel.Meeting> rows = new ArrayList<>(
                        board.board().meetings().values());
                rows.sort(Comparator.comparing(BoardModel.Meeting::meetingId));
                meetings.put(company, List.copyOf(rows));
            }
        }
        if (state.governance() != null) {
            String company = state.governance().board().charter().companyPartyId();
            charters.putIfAbsent(company, state.governance().board().charter());
            List<BoardModel.Meeting> rows = new ArrayList<>(
                    state.governance().board().meetings().values());
            rows.sort(Comparator.comparing(BoardModel.Meeting::meetingId));
            meetings.putIfAbsent(company, List.copyOf(rows));
        }
        return new PeriodicFrame(Map.copyOf(charters), Map.copyOf(meetings),
                state.information() == null ? null : state.information().information(),
                informationConfig == null ? null : informationConfig.recallPolicy(),
                state.roles() == null ? null : state.roles().access());
    }

    /**
     * 周期治理的受信绑定：席位、到会/回避、经理、实读与回忆全部落到本世界。
     *
     * @return Access 与 BoardAccess 的同一实现
     */
    public PeriodicModel.Access periodicAccess() {
        return new PeriodicWorldAccess(this);
    }

    /**
     * 董事会读取资格：只按本公司章程当前绑定回答（不看 RoleAccess，不设有效期）。
     *
     * @return 董事会回调
     */
    private BoardAccess periodicBoards() {
        Map<String, BoardModel.Charter> charters = new LinkedHashMap<>(periodicFrame().charters());
        return (company, person, at) -> {
            BoardModel.Charter charter = charters.get(company);
            return charter != null && person != null && charter.seatOf(person) != null;
        };
    }

    /**
     * 只读：某公司的周期状态（旧档或未初始化返回空）。
     *
     * @param companyPartyId 公司组织
     * @return 周期状态
     */
    public synchronized Optional<PeriodicModel.CompanyPeriods> periodicOf(
            String companyPartyId) {
        EngineeringRun run = state.engineering();
        return run == null ? Optional.empty() : run.periodicOf(companyPartyId);
    }

    /**
     * 人物侧周期投影：只给本人可见的期间、窗口、材料引用与本人动作状态。
     *
     * <p>不含全局 position、私有 sourceRef、别家公司账、他人选票内容与 God 报表真值。</p>
     *
     * @param personPartyId  人物
     * @param companyPartyId 公司组织
     * @return 只读投影；无可看内容时为空表
     */
    public synchronized java.util.Map<String, Object> periodicRoleView(String personPartyId,
            String companyPartyId) {
        java.util.Map<String, Object> view = new java.util.LinkedHashMap<>();
        Optional<PeriodicModel.CompanyPeriods> periods = periodicOf(companyPartyId);
        if (periods.isEmpty()) {
            return view;
        }
        boolean seat = new PeriodicWorldAccess(this).seatOf(companyPartyId, personPartyId,
                state.timeMillis()) != null;
        boolean manager = activeManager(state.roles(), personPartyId, companyPartyId,
                state.timeMillis());
        if (!seat && !manager) {
            // 无成员身份不返回任何期间/材料/证据/会议；God 审计走 periodicGodView 自有行。
            return view;
        }
        view.put("companyPartyId", companyPartyId);
        view.put("seat", seat);
        view.put("manager", manager);
        view.put("periods", periodicPeriodRows(periods.get(),
                boardOfCompany(companyPartyId).orElse(null), personPartyId, state.timeMillis(),
                seat, manager));
        return view;
    }

    /**
     * 期间行投影：只读入参帧的周期状态与治理董事会，人物投影与 v6 输入共用同一实现。
     *
     * <p>不含全局 position、摘要、私有材料来源、他人选票内容与 God 报表真值；证据只给本人
     * 评分可用的真实引用及允许维度。</p>
     */
    private static java.util.List<java.util.Map<String, Object>> periodicPeriodRows(
            PeriodicModel.CompanyPeriods periods, BoardRun board, String personPartyId,
            long now, boolean seat, boolean manager) {
        java.util.List<java.util.Map<String, Object>> rows = new java.util.ArrayList<>();
        for (PeriodicModel.Snapshot snapshot : periods.snapshots()) {
            java.util.Map<String, Object> row = new java.util.LinkedHashMap<>();
            row.put("period", snapshot.period());
            row.put("capturedAt", snapshot.capturedAt());
            row.put("materialDocId", snapshot.materialDocId());
            row.put("materialVersion", snapshot.materialVersion());
            java.util.List<java.util.Map<String, Object>> evidence = new java.util.ArrayList<>();
            for (String ref : snapshot.evidenceRefs()) {
                java.util.List<String> dimensions = PeriodicWorldEngine.dimensionsFor(ref);
                if (dimensions.isEmpty()) {
                    // 私有材料来源与其它内部引用不作为评分证据输出。
                    continue;
                }
                java.util.Map<String, Object> entry = new java.util.LinkedHashMap<>();
                entry.put("ref", ref);
                entry.put("dimensions", dimensions);
                evidence.add(entry);
            }
            row.put("evidence", evidence);
            BoardModel.Meeting meeting = board == null ? null
                    : board.board().meeting(snapshot.meetingId());
            if (meeting != null) {
                row.put("meetingId", meeting.meetingId());
                row.put("opensAt", meeting.opensAt());
                row.put("closesAt", meeting.closesAt());
                row.put("meetingStatus", meeting.status().name());
            }
            boolean mine = false;
            for (PeriodicModel.Ballot ballot : periods.ballots()) {
                if (ballot.period() == snapshot.period()
                        && ballot.personPartyId().equals(personPartyId)) {
                    mine = true;
                }
            }
            row.put("myBallotSubmitted", mine);
            row.put("kind", snapshot.period() % PeriodicModel.FORMAL_EVERY_PERIODS == 0
                    ? "QUARTERLY" : "MONTHLY");
            long deadline = safeAdd(snapshot.capturedAt(),
                    periods.policy().disclosureWindowMillis());
            row.put("deadline", deadline);
            int published = 0;
            boolean late = false;
            for (PeriodicModel.Release release : periods.releases()) {
                if (release.period() == snapshot.period()) {
                    published++;
                    late = late || release.late();
                }
            }
            row.put("publishedVersions", published);
            row.put("publicDocId", published == 0 ? ""
                    : PeriodicWorldEngine.publicDocId(snapshot.companyPartyId(),
                    snapshot.period()));
            row.put("late", late);
            boolean missed = false;
            for (PeriodicModel.Missed marker : periods.missed()) {
                missed = missed || marker.period() == snapshot.period();
            }
            row.put("missed", missed);
            boolean scored = false;
            for (PeriodicModel.Score score : periods.scores()) {
                scored = scored || score.period() == snapshot.period();
            }
            row.put("reviewClosed", scored);
            java.util.Map<String, Object> draftView = null;
            for (PeriodicModel.Draft draft : periods.drafts()) {
                if (draft.period() != snapshot.period()) {
                    continue;
                }
                int approvals = 0;
                for (PeriodicModel.Approval approval : periods.approvals()) {
                    if (approval.draftId().equals(draft.draftId())
                            && approval.draftVersion() == draft.version()) {
                        approvals++;
                    }
                }
                java.util.Map<String, Object> entry = new java.util.LinkedHashMap<>();
                entry.put("draftId", draft.draftId());
                entry.put("docId", draft.docId());
                entry.put("version", draft.version());
                entry.put("preparedBy", draft.preparedBy());
                entry.put("preparedAt", draft.preparedAt());
                entry.put("approvals", approvals);
                draftView = entry;
            }
            if (draftView != null) {
                row.put("myDraft", draftView);
            }
            boolean approved = false;
            for (PeriodicModel.Approval approval : periods.approvals()) {
                approved = approved || (approval.period() == snapshot.period()
                        && approval.approverPersonId().equals(personPartyId));
            }
            row.put("myApproval", approved);
            java.util.Map<String, Object> pending = pendingAuthorization(periods,
                    snapshot.period(), personPartyId, seat, manager, now);
            if (pending != null) {
                row.put("pendingAuthorization", pending);
            }
            rows.add(row);
        }
        return rows;
    }

    /**
     * 本人此刻可见且可执行的有效未消费授权（只读传入帧与 {@code now}）。
     *
     * <p>经理能看到本公司本期的有效未消费授权（用于签发/复核）；被指定发布人只看到属于自己
     * 的那一条；其他董事、他公司与普通人一律看不到。已消费、已过期（右开）的授权不再给出，
     * 但历史记录仍保留在状态里，不因投影变化被抹除。</p>
     *
     * @param periods        本公司周期状态
     * @param period         期间
     * @param personPartyId  查看人
     * @param seat           本人此刻是否本公司在任董事
     * @param manager        本人此刻是否本公司现任经理
     * @param now            查看时点
     * @return 可执行授权；没有则返回 null
     */
    private static java.util.Map<String, Object> pendingAuthorization(
            PeriodicModel.CompanyPeriods periods, long period, String personPartyId,
            boolean seat, boolean manager, long now) {
        java.util.Map<String, Object> latest = null;
        long latestIssuedAt = Long.MIN_VALUE;
        for (PeriodicModel.Authorization authorization : periods.authorizations()) {
            if (authorization.period() != period) {
                continue;
            }
            if (authorization.consumedAt() != 0 || now >= authorization.expiresAt()) {
                continue;
            }
            boolean mine = authorization.publisherPersonId().equals(personPartyId);
            if (!mine && !manager) {
                continue;
            }
            if (mine && !seat && !manager) {
                // 失席/撤权后本人不再有可执行的发布资格，投影不再给出授权。
                continue;
            }
            if (authorization.issuedAt() < latestIssuedAt) {
                continue;
            }
            java.util.Map<String, Object> entry = new java.util.LinkedHashMap<>();
            entry.put("authorizationId", authorization.authorizationId());
            entry.put("publisherPersonId", authorization.publisherPersonId());
            entry.put("expiresAt", authorization.expiresAt());
            entry.put("draftId", authorization.draftId());
            entry.put("draftVersion", authorization.draftVersion());
            latest = entry;
            latestIssuedAt = authorization.issuedAt();
        }
        return latest;
    }

    /**
     * God 侧周期审计：在人物投影之外补真实 position、摘要与各席/审批/发布计数。
     *
     * @param companyPartyId 公司组织
     * @return 只读审计投影
     */
    public synchronized java.util.Map<String, Object> periodicGodView(String companyPartyId) {
        java.util.Map<String, Object> view = new java.util.LinkedHashMap<>();
        Optional<PeriodicModel.CompanyPeriods> periods = periodicOf(companyPartyId);
        if (periods.isEmpty()) {
            return view;
        }
        // God 审计不复用人物投影的空 person 路径：显式给出全部期间行，不冒充任何角色。
        view.put("companyPartyId", companyPartyId);
        view.put("seat", false);
        view.put("manager", false);
        view.put("periods", periodicPeriodRows(periods.get(),
                boardOfCompany(companyPartyId).orElse(null), "", state.timeMillis(), false, false));
        java.util.List<java.util.Map<String, Object>> rows = new java.util.ArrayList<>();
        for (PeriodicModel.Snapshot snapshot : periods.get().snapshots()) {
            java.util.Map<String, Object> row = new java.util.LinkedHashMap<>();
            row.put("period", snapshot.period());
            row.put("capturedAt", snapshot.capturedAt());
            row.put("position", snapshot.position());
            row.put("basisDigest", snapshot.basisDigest());
            row.put("statementDigest", snapshot.statementDigest());
            row.put("materialDocId", snapshot.materialDocId());
            row.put("materialVersion", snapshot.materialVersion());
            row.put("ballots", periods.get().ballots().stream()
                    .filter(b -> b.period() == snapshot.period()).count());
            row.put("scores", periods.get().scores().stream()
                    .filter(s -> s.period() == snapshot.period()).count());
            row.put("releases", periods.get().releases().stream()
                    .filter(r -> r.period() == snapshot.period()).count());
            rows.add(row);
        }
        view.put("godPeriods", rows);
        return view;
    }

    /**
     * 按公司取工程经营状态（只读）。
     *
     * @param companyPartyId 公司组织 partyId
     * @return 工程状态；旧档或非工程公司返回空
     */
    public synchronized Optional<EngineeringModel.State> engineeringStateOf(
            String companyPartyId) {
        requireText(companyPartyId, "公司");
        EngineeringRun run = state.engineering();
        if (run == null) {
            return Optional.empty();
        }
        return Optional.ofNullable(run.stateOf(companyPartyId));
    }

    /**
     * 只读 God 公司审计：报表口径来自真实账户与纯核 ReportContext，不面向角色输入。
     *
     * @param companyPartyId 工程公司
     * @return 审计视图；未知公司为空
     */
    /** 从真实资本/分红状态与事件重算只读 ReportContext，不复制第二账。 */
    private EngineeringModel.ReportContext reportContextOf(String companyPartyId) {
        return reportContextOf(state, companyPartyId);
    }

    /**
     * 从给定快照的真实资本/分红状态与事件重算只读 ReportContext。
     *
     * <p>必须显式给基准快照：历史输入重生成（跨 JVM 恢复）时运行层的当前 state 尚未装配，
     * 不能用它代替被核对的历史帧。</p>
     */
    private EngineeringModel.ReportContext reportContextOf(WorldState base, String companyPartyId) {
        EngineeringRun.CompanySpec spec = engineeringConfig.specOf(companyPartyId);
        if (spec == null) {
            return EngineeringModel.ReportContext.none();
        }
        BigDecimal net = BigDecimal.ZERO.setScale(2);
        BigDecimal declared = BigDecimal.ZERO.setScale(2);
        BigDecimal unpaid = BigDecimal.ZERO.setScale(2);
        try {
            for (WorldCommit commit : commitSource.commits()) {
                for (WorldEvent event : commit.events()) {
                    if (!"CAPITAL_FLOW_V1".equals(event.type())) {
                        continue;
                    }
                    CapitalFlowReport report = mapper.readValue(event.payload(),
                            CapitalFlowReport.class);
                    if (report.toAccountId().equals(spec.companyAccountId())) {
                        net = net.add(report.amount());
                    } else if (report.fromAccountId().equals(spec.companyAccountId())) {
                        net = net.subtract(report.amount());
                    }
                }
            }
        } catch (IOException unreadable) {
            throw new IllegalStateException("资本事件不可读", unreadable);
        }
        if (base.dividends() != null) {
            for (DividendModel.Claim claim : base.dividends().claims().values()) {
                DividendModel.Scheme scheme = base.dividends().schemes().get(claim.schemeId());
                if (scheme == null || !scheme.issuerOwnerId().equals(spec.companyOwnerId())) {
                    continue;
                }
                declared = declared.add(claim.face());
                unpaid = unpaid.add(claim.face().subtract(claim.paid())
                        .subtract(claim.impairment()));
            }
        }
        return new EngineeringModel.ReportContext(net, declared,
                unpaid.max(BigDecimal.ZERO.setScale(2)));
    }

    public synchronized Optional<CompanyAudit> companyAudit(String companyPartyId) {
        EngineeringModel.State state = engineeringStateOf(companyPartyId).orElse(null);
        if (state == null) {
            return Optional.empty();
        }
        EngineeringModel.Report report = EngineeringModel.validate(state, snapshot().accounts(),
                reportContextOf(companyPartyId));
        BoardRun board = boardOfCompany(companyPartyId).orElse(null);
        return Optional.of(new CompanyAudit(companyPartyId, report.companyCash(),
                report.arCurrent(), report.arRetention(), report.payable(), report.allowance(),
                report.obligation(), report.equity(), state.contracts().size(),
                state.workOrders().size(), board == null ? 0 : board.board().meetings().size(),
                report.balanced()));
    }

